var required = ["background", "surface", "on_surface", "on_surface_variant",
    "primary", "on_primary", "primary_container", "on_primary_container",
    "secondary", "on_secondary", "secondary_container", "on_secondary_container",
    "tertiary", "on_tertiary", "tertiary_container", "on_tertiary_container",
    "error", "on_error", "error_container", "on_error_container",
    "outline", "outline_variant", "surface_container", "surface_container_low",
    "surface_container_high", "surface_container_highest", "surface_container_lowest"]

function parse(text) {
    var value = JSON.parse(text)
    if (!value || value.version !== 1 || value.generator !== "matugen"
        || ["dark", "light"].indexOf(value.mode) === -1
        || typeof value.wallpaper !== "string" || !value.colors)
        throw new Error("Invalid Matugen palette header")
    required.forEach(function(key) {
        if (typeof value.colors[key] !== "string" || !/^#[0-9a-fA-F]{6}$/.test(value.colors[key]))
            throw new Error("Invalid Matugen role: " + key)
    })
    return value
}
